create extension if not exists pgcrypto;
create type user_role as enum ('seller','admin');
create type order_status as enum ('draft','submitted','offer_pending','offer_sent','offer_accepted','awaiting_shipment','tracking_added','shipped','delivered','in_review','final_offer_sent','final_offer_accepted','payment_pending','paid','completed','cancelled','disputed');
create table profiles(id uuid primary key references auth.users on delete cascade,role user_role not null default 'seller',full_name text,email text,phone text,created_at timestamptz default now());
create table buy_orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,seller_id uuid references profiles,status order_status default 'draft',collection_type text,notes text,estimated_payout numeric(12,2),final_payout numeric(12,2),tracking_number text,carrier text,created_at timestamptz default now(),updated_at timestamptz default now());
create table buy_order_items(id uuid primary key default gen_random_uuid(),buy_order_id uuid references buy_orders on delete cascade,category text,card_name text,set_name text,card_number text,rarity text,condition text,submitted_quantity int default 0,received_quantity int,market_price numeric(12,2));
create table buy_order_media(id uuid primary key default gen_random_uuid(),buy_order_id uuid references buy_orders on delete cascade,storage_path text not null,media_type text,created_at timestamptz default now());
create table offers(id uuid primary key default gen_random_uuid(),buy_order_id uuid references buy_orders on delete cascade,kind text check(kind in('initial','final')),recommended_amount numeric(12,2),manual_amount numeric(12,2),customer_amount integer,accepted_at timestamptz,created_at timestamptz default now());
create table order_status_events(id uuid primary key default gen_random_uuid(),buy_order_id uuid references buy_orders on delete cascade,status order_status,note text,created_at timestamptz default now());
create table payout_methods(id uuid primary key default gen_random_uuid(),seller_id uuid references profiles,type text check(type in('cash_app','venmo','ach')),details jsonb,created_at timestamptz default now());
create table payouts(id uuid primary key default gen_random_uuid(),buy_order_id uuid references buy_orders,method_id uuid references payout_methods,amount numeric(12,2),status text default 'pending',confirmation_notes text,paid_at timestamptz);
create table inspection_reports(id uuid primary key default gen_random_uuid(),buy_order_id uuid unique references buy_orders,condition_issues text,missing_cards text,extra_cards text,adjustments text,opening_video_recorded boolean default true,opening_video_url text,completed_at timestamptz);
create table inspection_report_items(id uuid primary key default gen_random_uuid(),report_id uuid references inspection_reports on delete cascade,buy_order_item_id uuid references buy_order_items,received_quantity int,condition text,adjustment numeric(12,2));
create table card_catalog(id uuid primary key default gen_random_uuid(),name text,set_name text,card_number text,rarity text,image_url text,metadata jsonb);
create table market_price_snapshots(id uuid primary key default gen_random_uuid(),card_id uuid references card_catalog,source text,market_price numeric(12,2),captured_at timestamptz default now());
create table ebay_comp_snapshots(id uuid primary key default gen_random_uuid(),card_id uuid references card_catalog,sold_average numeric(12,2),sample_size int,raw_data jsonb,captured_at timestamptz default now());
create table inventory_items(id uuid primary key default gen_random_uuid(),sku text unique,source_buy_order uuid references buy_orders,card_name text,set_name text,card_number text,rarity text,condition text,quantity int,purchase_cost numeric(12,2),suggested_ebay_price numeric(12,2),expected_fees numeric(12,2),expected_shipping numeric(12,2),sold_price numeric(12,2),status text default 'pending_listing',listed_at timestamptz,sold_at timestamptz);
create table ebay_export_batches(id uuid primary key default gen_random_uuid(),filename text,item_count int,created_by uuid references profiles,created_at timestamptz default now());
create table admin_notes(id uuid primary key default gen_random_uuid(),buy_order_id uuid references buy_orders,author_id uuid references profiles,note text,created_at timestamptz default now());
create table activity_log(id uuid primary key default gen_random_uuid(),actor_id uuid references profiles,buy_order_id uuid references buy_orders,action text,data jsonb,created_at timestamptz default now());
alter table profiles enable row level security;alter table buy_orders enable row level security;alter table buy_order_items enable row level security;alter table buy_order_media enable row level security;
create policy "read own profile" on profiles for select using(auth.uid()=id);
create policy "read own orders" on buy_orders for select using(seller_id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin'));
create policy "create own orders" on buy_orders for insert with check(seller_id=auth.uid());
create policy "read own items" on buy_order_items for select using(exists(select 1 from buy_orders o where o.id=buy_order_id and (o.seller_id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin'))));
create policy "read own media" on buy_order_media for select using(exists(select 1 from buy_orders o where o.id=buy_order_id and (o.seller_id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin'))));
